#[test]
fn sixth_root_gpl_matches_independent_period_components() {
    let bits = 1600;
    let tolerance = Float::parse("1e-385", Some(bits)).unwrap();
    let reference_error = Float::parse("1e-390", Some(bits)).unwrap();
    let radius_limit = Float::parse("1e-450", Some(bits)).unwrap();
    for &(word, imaginary, reference) in REFERENCES {
        let value = EndpointOneGplEvaluator::new(word)
            .unwrap()
            .evaluate_ball(bits)
            .unwrap();
        let component = if imaginary { value.im } else { value.re };
        let reference = Float::parse(reference, Some(bits)).unwrap();
        assert!(
            (component.center.clone() - &reference).norm() < tolerance,
            "{word:?}"
        );
        assert!(component.radius < radius_limit, "{word:?}");
        assert!(
            component.intersects(&RealBall::new(reference, reference_error.clone())),
            "{word:?}"
        );
    }
}

#[test]
fn unit_alphabet_low_weights_shuffle_conjugation_and_checked_tags() {
    let bits = 256;
    let ball = |word: &[GplLetter]| {
        EndpointOneGplEvaluator::new(word)
            .unwrap()
            .evaluate_ball(bits)
            .unwrap()
    };
    let empty = ball(&[]);
    assert_eq!(empty.re.center, Float::with_val(bits, 1));
    assert!(empty.re.radius.is_zero());
    for (a, conjugate) in [(R1, R5), (R2, R4), (MinusOne, MinusOne)] {
        let single = ball(&[a]);
        assert!(single.intersects(&ball(&[conjugate]).conj()));
        let other = ball(&[MinusOne]);
        let product = &single * &other;
        let shuffle = ball(&[a, MinusOne]) + ball(&[MinusOne, a]);
        assert!(product.intersects(&shuffle));
        let tagged = endpoint_one_gpl(&[a, MinusOne]).unwrap();
        let tracked = tagged
            .evaluate_tracked(&HashMap::<Atom, TrackedComplex>::new(), bits)
            .unwrap();
        assert!(tracked.ball.intersects(&ball(&[a, MinusOne])));
    }
    let minus_one = ball(&[MinusOne]);
    let logarithm = Float::with_val(bits, 2).log();
    assert!(minus_one.re.contains(&logarithm));
    assert!(minus_one.im.contains(&Float::new(bits)));
    for bad in [vec![One], vec![Zero], vec![R1, Zero], vec![R4; 7]] {
        assert!(endpoint_one_gpl(&bad).is_err());
    }
    assert!(parse_tags(&[]).is_err());
    let unsupported = LETTERS.call(Atom::num(2));
    assert!(parse_tags(&[unsupported.as_view()]).is_err());
}

#[test]
#[ignore = "explicit twenty-thousand-digit unit-alphabet GPL acceptance"]
fn unit_alphabet_gpl_twenty_thousand_digits() {
    let bits = Float::decimal_digits_to_bits(20_000.0).unwrap() + 128;
    for &(word, imaginary, _) in REFERENCES {
        let evaluator = EndpointOneGplEvaluator::new(word).unwrap();
        let value = evaluator.evaluate_ball(bits).unwrap();
        let refined = evaluator.evaluate_ball(bits + 128).unwrap();
        assert!(value.contains_ball(&refined), "{word:?}");
        let precision = TrackedComplex::from_ball(value, ErrorQuality::Bounded).precision();
        let component = if imaginary {
            precision.imaginary
        } else {
            precision.real
        };
        assert!(
            component.significant_digits().unwrap() >= 20_000,
            "{word:?}"
        );
    }
}
